const HIGH_CHEERS_SLUG="master_cdbb557d24080162a681ae5c";
async function refreshGameVersions(){
 const all=await loadVersions();
 gameVersions=all.filter(v=>Number(v.sort_order)>=29&&Number(v.sort_order)<100);
 const current=gameVersions.find(v=>v.is_current)||gameVersions.find(v=>v.slug===HIGH_CHEERS_SLUG);
 if(!current)throw new Error("スコア閲覧用のゲームバージョンがありません。");
 const saved=localStorage.getItem("popn-game-version");
 selectedGameVersion=gameVersions.find(v=>v.id===saved)||current;
 const select=$("#gameVersionSelect");
 select.innerHTML=gameVersions.map(v=>`<option value="${attr(v.id)}">${attr(v.name)}</option>`).join("");
 select.value=selectedGameVersion.id;
 const link=$("#syncDialog .official-link");
 if(link){link.hidden=!selectedGameVersion.sync_path;if(selectedGameVersion.sync_path)link.href=`https://p.eagate.573.jp${selectedGameVersion.sync_path}playdata/mu_top.html?page=0&version=-1&bemani=0&category=0&keyword=&sort=music&sort_type=up`;}
}
