async function importHash(){const marker="#popn-sync-gzip=";if(!location.hash.startsWith(marker))return;const notice=syncNotice(),status=notice.querySelector("[data-sync-save-status]"),progress=notice.querySelector("[data-sync-save-progress]");try{const binary=atob(decodeURIComponent(location.hash.slice(marker.length))),bytes=Uint8Array.from(binary,char=>char.charCodeAt(0)),text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text(),payload=JSON.parse(text);if(payload.type!=="POPN_SCORE_SYNC"||!Array.isArray(payload.records))throw new Error("同期データが不正です。");
 const source=new URL(payload.source_url||"https://invalid.example/");
 const sourcePath=source.pathname;
 const syncVersion=gameVersions.find(v=>v.sync_path===sourcePath);
 if(source.origin!=="https://p.eagate.573.jp"||!/^\/game\/popn\/popn[0-9]+\/$/.test(sourcePath)||!syncVersion)
   throw new Error("同期元の公式サイトURLが未登録です。管理者にURLの登録を依頼してください。保存はしていません。");const officialPopnClass=Number(payload.popn_class),hasOfficialPopnClass=payload.popn_class!==null&&payload.popn_class!==undefined&&Number.isFinite(officialPopnClass)&&officialPopnClass>=0;history.replaceState(null,"",location.pathname+location.search);progress.max=Math.max(1,payload.records.filter(x=>Number(x.score)>0||Number(x.version_score)>0||String(x.medal_code||"none").toLowerCase()!=="none"||String(x.rank_code||"none").toLowerCase()!=="none").length);status.textContent=`0/${progress.max}譜面を保存する準備中`;const diagnosis=await diagnoseSyncMatches(payload.records);const diagnosticText=`同期照合（譜面数）\nキー一致 ${diagnosis.key_match}／3項目・曲名＋アーティスト一致 ${diagnosis.identity_match}／要確認 ${diagnosis.title_only_match}／未登録 ${diagnosis.unmatched}`;status.textContent=diagnosticText.replaceAll("\n","・");if(diagnosis.title_only_match>0){const details=await diagnoseTitleOnlyMatches(payload.records);const lines=details.map((item,i)=>`${i+1}. 公式：${item.input_genre} / ${item.input_title} / ${item.input_artist}\n   登録：${item.song_genre} / ${item.song_title} / ${item.song_artist}`);alert(`${diagnosticText}\n\n安全に一意照合できない曲があるため、保存を中止しました。以下の曲情報だけを共有してください（スコア・ユーザーIDは含まれません）。\n\n${lines.join("\n\n")}`);return;}const result=await syncScores(payload.records,info=>{progress.max=Math.max(1,info.total);progress.value=info.done;status.textContent=`${info.done}/${info.total}譜面を${syncVersion.name}へ保存中${info.retries?`・再試行 ${info.retries}回`:""}`;},syncVersion);if(hasOfficialPopnClass&&syncVersion.is_current)await saveOfficialPopnClass(officialPopnClass);progress.value=progress.max;status.textContent=`${syncVersion.name}へ保存完了：${result.saved}譜面・曲マスター未登録 ${result.unmatched}譜面（条件を満たすデータを仮保存）${hasOfficialPopnClass?`・ポップンクラス ${officialPopnClass.toFixed(2)}`:""}`;try{if(result.saved>0){selectedGameVersion=syncVersion;localStorage.setItem("popn-game-version",syncVersion.id);}await refreshAuth();}catch(refreshError){console.error("Score reload after sync failed",refreshError);status.textContent+="・画面の更新に失敗しました（再読み込みしてください）";}if(!result.failed&&result.saved&&selectedGameVersion?.id===syncVersion.id){try{await savePsrSnapshot(scores,officialPopnClass,{automatic:true});status.textContent+="・PSR履歴を自動保存しました";}catch(snapshotError){console.error("PSR snapshot save failed",snapshotError);status.textContent+="・PSR履歴の保存に失敗しました";}}notice.querySelector("strong").textContent=result.failed?"スコアの一部を保存しました":"同期完了";if(result.failed){alert(`同期は一部完了しました。保存 ${result.saved}譜面／保存失敗 ${result.failed}譜面／曲マスター未登録 ${result.unmatched}譜面（仮保存対象は承認後に反映）。失敗分は時間をおいて再同期してください。`);}else{alert(`同期完了：${syncVersion.name}へ${result.saved}譜面を保存しました。曲マスター未登録 ${result.unmatched}譜面（仮保存対象は承認後に反映）。${hasOfficialPopnClass?` ポップンクラス ${officialPopnClass.toFixed(2)}。`:""}`);}notice.remove();}catch(error){status.textContent=`保存エラー：${error.message||error}`;notice.querySelector("strong").textContent="同期データの保存に失敗しました";alert(`同期に失敗しました：${error.message||error}`);}}

