// Compute from the full, unfiltered catalog, not the visible song list or PSR selection.
function showLevelAverages(){
  const startInput=$("#averageLevelFrom"),endInput=$("#averageLevelTo"),output=$("#averageScoreResult");
  const start=Number(startInput.value),end=Number(endInput.value);
  if(!startInput.value||!endInput.value||!Number.isInteger(start)||!Number.isInteger(end)||start<1||end>50||start>end){
    output.textContent="レベルは1～50の範囲で、開始レベルを終了レベル以下にして選択してください。";
    return;
  }
  const averages=levelScoreAverages(scores,start,end);
  output.innerHTML=`<table class="average-score-table"><thead><tr><th scope="col">レベル</th><th scope="col">歴代スコア</th><th scope="col">今作スコア</th></tr></thead><tbody>${averages.map(row=>`<tr><th scope="row">${row.level}</th><td>${row.historyCount?row.historyAverage.toFixed(2):"－"}</td><td>${row.currentCount?row.currentAverage.toFixed(2):"－"}</td></tr>`).join("")}</tbody></table>`;
}
