function versionSlug(name){const normalized=String(name||"").normalize("NFKD").toLowerCase().replace(/[’'`]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"");if(normalized)return normalized;let hash=2166136261;for(const char of String(name||"")){hash^=char.codePointAt(0);hash=Math.imul(hash,16777619);}return`version-${(hash>>>0).toString(16).padStart(8,"0")}`;}
async function openAdminEditor(kind,item={}){adminEdit={kind,item};const fields=$("#adminEditFields");if(kind==="version"){
 if(!item.id){const existing=await loadVersions();const next=Math.max(29,...existing.filter(v=>Number(v.sort_order)<100).map(v=>Number(v.sort_order)||0))+1;item.sort_order=next;}
 $("#adminEditTitle").textContent=item.id?"バージョン編集":"バージョン追加";fields.innerHTML=`<label>表示名<input name="name" required value="${attr(item.name)}"></label><label>識別名<input name="slug" required readonly pattern="[a-z0-9_-]+" value="${attr(item.slug)}"><small>${item.id?"識別名は変更できません。":"表示名から自動入力されます。"}</small></label><label>公式サイトURL（同期対応時は必須）<input name="sync_path" type="url" value="${attr(item.sync_path?`https://p.eagate.573.jp${item.sync_path}`:"")}" placeholder="https://p.eagate.573.jp/game/popn/popn30/"><small>公式サイトの曲データページURLを登録。未登録のURLからは同期できません。</small></label><label>並び順<input name="sort_order" type="number" required value="${item.sort_order??0}"></label><label class="check-row"><input name="is_current" type="checkbox" ${item.is_current?"checked":""}>現行バージョン</label><label class="check-row"><input name="is_active" type="checkbox" ${item.is_active!==false?"checked":""}>有効</label>`;if(!item.id){const nameInput=fields.querySelector('[name="name"]'),slugInput=fields.querySelector('[name="slug"]'),syncSlug=()=>{slugInput.value=versionSlug(nameInput.value);};nameInput.addEventListener("input",syncSlug);syncSlug();}}else{const versions=await loadVersions(),generated=[...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,"0")).join("");$("#adminEditTitle").textContent=item.id?"曲マスター編集":"曲マスター追加";fields.innerHTML=`<label>曲ID<input name="master_key" readonly value="${attr(item.master_key||generated)}"><small>新規追加時は自動設定されます。</small></label><label>バナー画像URL（任意）<input name="banner_url" type="url" value="${attr(item.banner_url)}" placeholder="https://..."></label><label class="banner-upload">バナー画像をアップロード（任意）<input name="banner_file" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><small>画像を選ぶとURLより優先します（2MB以下）。</small></label><div class="form-grid"><label>ジャンル<input name="genre" required value="${attr(item.genre)}"></label><label>曲名<input name="title" required value="${attr(item.title)}"></label></div><label>アーティスト<input name="artist" required value="${attr(item.artist)}"></label><div class="master-levels">${[["LIGHT","light_level"],["NORMAL","normal_level"],["HYPER","hyper_level"],["EX","ex_level"]].map(([label,key])=>`<label>${label}<input name="${key}" type="number" min="1" max="50" value="${item[key]||""}" placeholder="なし"></label>`).join("")}</div><label>登場バージョン<select name="version_id"><option value="">未設定</option>${versions.map(x=>`<option value="${x.id}" ${x.id===item.version_id?"selected":""}>${attr(x.name)}</option>`).join("")}</select></label>`;}$("#adminEditDialog").showModal();}
$("#adminAddButton").addEventListener("click",()=>openAdminEditor(currentAdminTab()==="versions"?"version":"song"));
$("#adminContent").addEventListener("click",async event=>{const song=event.target.closest("[data-edit-song]"),version=event.target.closest("[data-edit-version]"),removeVersion=event.target.closest("[data-delete-version]"),approve=event.target.closest("[data-approve-request]"),approveBanner=event.target.closest("[data-approve-banner]"),rejectBanner=event.target.closest("[data-reject-banner]"),status=event.target.closest("[data-status-id]"),reply=event.target.closest("[data-reply-id]"),exportUser=event.target.closest("[data-export-user]"),remove=event.target.closest("[data-delete-user]"),removeFeedback=event.target.closest("[data-delete-feedback]");try{if(song)await openAdminEditor("song",JSON.parse(decodeURIComponent(song.dataset.editSong)));if(version)await openAdminEditor("version",JSON.parse(decodeURIComponent(version.dataset.editVersion)));if(removeVersion&&await askConfirm(`${decodeURIComponent(removeVersion.dataset.versionName)} を削除しますか？\nこのバージョンが設定されている曲は「登場バージョン：未設定」になります。`)){await deleteVersion(removeVersion.dataset.deleteVersion);await renderAdmin();await populateAdminMasterFilters();await refreshGameVersions();alert("バージョンを削除しました。");}if(approve){await approveSongRequest(approve.dataset.approveRequest);await renderAdmin();await refreshAdminNotices();alert("曲マスターへ登録・統合しました。");}if(approveBanner){await approveBannerRequest(approveBanner.dataset.approveBanner,decodeURIComponent(approveBanner.dataset.bannerPath));await renderAdmin();await refreshAdminNotices();alert("バナーを曲データへ反映しました。");}if(rejectBanner&&await askConfirm("このバナー依頼を却下しますか？")){await rejectBannerRequest(rejectBanner.dataset.rejectBanner);await renderAdmin();await refreshAdminNotices();}if(status){await updateStatus(status.dataset.statusTable,status.dataset.statusId,status.dataset.status);await renderAdmin();await refreshAdminNotices();}if(reply){const message=await askText("ユーザーへの返信を入力してください。");if(message!==null&&message.trim()){await updateStatus("feedback_reports",reply.dataset.replyId,"answered",message.trim());await renderAdmin();await refreshAdminNotices();}}if(removeFeedback&&await askConfirm("この要望・不具合を削除しますか？")){await deleteFeedback(removeFeedback.dataset.deleteFeedback);await renderAdmin();await refreshAdminNotices();alert("削除しました。");}if(exportUser){const name=decodeURIComponent(exportUser.dataset.userName),count=await exportUserScoresCsv(exportUser.dataset.exportUser,name);if(!count)alert("このユーザーには登録データがありません。");}if(remove&&await askConfirm(`${decodeURIComponent(remove.dataset.userName)} を削除しますか？\nスコアなど、このユーザーのデータも削除されます。`)){await deleteUser(remove.dataset.deleteUser);await renderAdmin();alert("ユーザーを削除しました。");}}catch(error){alert(error.message||error);}});
$("#adminContent").addEventListener("click",event=>{const button=event.target.closest("[data-admin-page]");if(button&&!button.disabled)setAdminPage(button.dataset.adminPage);});$("#adminContent").addEventListener("change",event=>{if(event.target.matches("[data-admin-page-select]"))setAdminPage(event.target.value);});
$("#adminEditForm").addEventListener("submit",async event=>{event.preventDefault();const raw=Object.fromEntries(new FormData(event.currentTarget)),errorBox=event.currentTarget.querySelector(".error");try{if(adminEdit.kind==="version"){
 const url=String(raw.sync_path||"").trim();
 let syncPath="";
 if(url){const source=new URL(url);const match=source.pathname.match(/^\/game\/popn\/(popn[0-9]+)(?:\/.*)?$/);if(source.origin!=="https://p.eagate.573.jp"||!match)throw new Error("公式サイトURLは https://p.eagate.573.jp/game/popn/popn番号/ 以下を指定してください。");syncPath=`/game/popn/${match[1]}/`;}
 await saveVersion({...raw,sync_path:syncPath,is_current:event.currentTarget.elements.is_current.checked,is_active:event.currentTarget.elements.is_active.checked},adminEdit.item.id);
 }else{const file=event.currentTarget.elements.banner_file?.files?.[0];if(file)raw.banner_url=await uploadSongBanner(file);await saveSong(raw,adminEdit.item.id);}$("#adminEditDialog").close();await refreshGameVersions();await renderAdmin();}catch(error){errorBox.textContent=error.message||error;}});

async function openMenuChild(id){$("#menuDialog").close();$(id).showModal();}
function showRivals(){const list=$("#rivalListContent");$("#rivalCount").textContent=`${rivals.length}/10人`;list.innerHTML=rivals.length?rivals.map(r=>`<div class="rival-entry"><strong>${attr(r.username)}</strong><button type="button" data-remove-rival="${attr(r.user_id)}" class="sub-button">★ 解除</button></div>`).join(""):'<p class="empty">登録したライバルはいません。</p>';}
$("#rivalListButton").addEventListener("click",async()=>{try{rivals=await loadRivals();showRivals();openMenuChild("#rivalListDialog");}catch(e){alert(e.message||e);}});
$("#rivalListContent").addEventListener("click",async event=>{const b=event.target.closest("[data-remove-rival]");if(!b)return;try{await toggleRival(b.dataset.removeRival);rivals=await loadRivals();showRivals();renderUsers(userRows,userPage,new Set(rivals.map(x=>x.user_id)),myUserId);}catch(e){alert(e.message||e);}});
$("#visibilityButton").addEventListener("click",async()=>{try{const p=await loadMyProfile(),f=$("#visibilityForm");$("#poptomoIdInput").value=p.poptomo_id||"";$("#poptomoPublicInput").checked=Boolean(p.poptomo_public);for(const key of ["highest_clear_public","popn_class_public","psr_public","rival_scores_public","rival_medals_public"])f.elements[key].checked=Boolean(p[key]);openMenuChild("#visibilityDialog");}catch(e){alert(e.message||e);}});
$("#visibilityForm").addEventListener("submit",async event=>{event.preventDefault();const f=event.currentTarget;try{await saveVisibility({poptomo_id:$("#poptomoIdInput").value,poptomo_public:$("#poptomoPublicInput").checked,...Object.fromEntries(["highest_clear_public","popn_class_public","psr_public","rival_scores_public","rival_medals_public"].map(k=>[k,f.elements[k].checked]))});f.querySelector(".error").textContent="";await refreshUsers();alert("公開設定を保存しました。");}catch(e){f.querySelector(".error").textContent=e.message||e;}});
async function openSongDetail(row){$("#songDetailTitle").textContent=`${row.title} / ${row.chart} Lv.${row.level}`;const box=$("#songDetailContent");box.textContent="ライバルのデータを取得中…";$("#songDetailDialog").showModal();try{const entries=await rivalSongScores(row.song_id,row.chart);const mine={username:"自分",score:row.score,medal_code:row.medal_code};box.innerHTML=[mine,...entries].map(r=>{const score=r.score==null?"非公開":Number(r.score)>0?Number(r.score).toLocaleString("ja-JP"):"－",info=r.medal_code==null?null:rivalMedalInfo(r.medal_code),medal=info==null?'<span class="rival-medal-private">非公開</span>':r.medal_code==="none"?'<span class="rival-medal-private">－</span>':Number(r.score)===100000?'<img src="./assets/cool-perfect.png" alt="COOL PERFECT" title="COOL PERFECT">':info.url?`<img src="${attr(info.url)}" alt="${attr(info.label)}" title="${attr(info.label)}">`:`<span class="rival-medal-private">${attr(info.label)}</span>`;return `<div class="rival-comparison"><strong>${attr(r.username)}</strong><span class="rival-history-score" aria-label="歴代スコア ${attr(score)}">${score}</span><span class="rival-medal">${medal}</span></div>`;}).join("")||"ライバルはいません。";}catch(e){box.textContent=e.message||String(e);}}
for(const id of ["#scoreList","#popclassContent"])$(id).addEventListener("click",event=>{if(event.target.closest("button,a,select,input"))return;const card=event.target.closest(".score-card-v300");if(!card)return;const edit=card.querySelector("[data-edit-score]");const row=scores.find(x=>String(x.id)===edit?.dataset.editScore);if(row)openSongDetail(row);});

onAuthChange(()=>refreshAuth(false));
try {
  await refreshAuth();
  window.psmLoading?.status("表示データを確認しています",84);
  await importHash();
  window.psmLoading?.status("表示を仕上げています",94);
  window.psmLoading?.finish();
} catch (error) {
  console.error("Initial loading failed:", error);
  window.psmLoading?.error(error);
}
